USE [siiid2];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

/*
    SIIID2 - Módulo FEDERAL
    Paso 02: carga de catálogos federales.

    Requiere ejecutar primero:
    20260813_01_modulo_federal_estructura.sql

    Resultado esperado:
    - 8 bienes jurídicos;
    - 73 delitos;
    - 124 subtipos;
    - 129 modalidades (83 comunes y 46 exclusivas federales);
    - 9,288 combinaciones de sábana (5,976 comunes y 3,312 federales).
*/

IF DB_NAME() <> N'siiid2'
BEGIN
    THROW 51100, 'El script debe ejecutarse en la base siiid2.', 1;
END;

IF OBJECT_ID(N'dbo.federal_catalogo_delito_sabana', N'U') IS NULL
BEGIN
    THROW 51101, 'Primero debe ejecutarse el script de estructura FEDERAL.', 1;
END;

IF NOT EXISTS (SELECT 1 FROM dbo.catalogo_modulo WHERE clave = N'FEDERAL' AND activo = 0)
BEGIN
    THROW 51102, 'El módulo FEDERAL no existe o ya está activo. Se cancela la carga de catálogos.', 1;
END;

