   OR EXISTS (SELECT 1 FROM dbo.federal_catalogo_delito)
   OR EXISTS (SELECT 1 FROM dbo.federal_catalogo_subtipo_delito)
   OR EXISTS (SELECT 1 FROM dbo.federal_catalogo_modalidad_delito)
   OR EXISTS (SELECT 1 FROM dbo.federal_catalogo_delito_sabana)
