        (9282, 129, 3, 8, 1, N'Extorsión', N'Extorsión (sin especificar)', N'Extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1),
        (9283, 129, 1, 8, 2, N'Extorsión', N'Extorsión (sin especificar)', N'Extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1),
