        (9285, 129, 3, 8, 2, N'Extorsión', N'Extorsión (sin especificar)', N'Extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1),
        (9286, 129, 1, 8, 3, N'Extorsión', N'Extorsión (sin especificar)', N'Extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1),
        (9287, 129, 2, 8, 3, N'Extorsión', N'Tentativa de extorsión (sin especificar)', N'Tentativa de extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1),
        (9288, 129, 3, 8, 3, N'Extorsión', N'Extorsión (sin especificar)', N'Extorsión (sin especificar)', N'4.04', N'4.04.03', 1, 1);

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_bien_juridico) <> 8
        THROW 51110, 'Conteo incorrecto en federal_catalogo_bien_juridico.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_delito) <> 73
        THROW 51111, 'Conteo incorrecto en federal_catalogo_delito.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_subtipo_delito) <> 124
        THROW 51112, 'Conteo incorrecto en federal_catalogo_subtipo_delito.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_modalidad_delito) <> 129
        THROW 51113, 'Conteo incorrecto en federal_catalogo_modalidad_delito.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_modalidad_delito WHERE es_fuero_federal = 0) <> 83
       OR (SELECT COUNT(*) FROM dbo.federal_catalogo_modalidad_delito WHERE es_fuero_federal = 1) <> 46
        THROW 51114, 'La separación de modalidades comunes/federales no coincide con 83/46.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_delito_sabana) <> 9288
        THROW 51115, 'Conteo incorrecto en federal_catalogo_delito_sabana.', 1;

    IF (SELECT COUNT(*) FROM dbo.federal_catalogo_delito_sabana WHERE es_fuero_federal = 0) <> 5976
       OR (SELECT COUNT(*) FROM dbo.federal_catalogo_delito_sabana WHERE es_fuero_federal = 1) <> 3312
        THROW 51116, 'La separación de sábana común/federal no coincide con 5,976/3,312.', 1;

    IF EXISTS
    (
        SELECT id_bien_juridico, clave1, bien_juridico, activo
        FROM dbo.catalogo_bien_juridico
        EXCEPT
        SELECT id_bien_juridico, clave1, bien_juridico, activo
        FROM dbo.federal_catalogo_bien_juridico
        WHERE id_bien_juridico <= 7
    )
    OR EXISTS
    (
        SELECT id_bien_juridico, clave1, bien_juridico, activo
        FROM dbo.federal_catalogo_bien_juridico
        WHERE id_bien_juridico <= 7
        EXCEPT
        SELECT id_bien_juridico, clave1, bien_juridico, activo
        FROM dbo.catalogo_bien_juridico
    )
        THROW 51120, 'Los 7 bienes comunes no coinciden con el catálogo Mensual.', 1;

    IF EXISTS
    (
        SELECT id_delito, id_bien_juridico, clave2, delito, activo
        FROM dbo.catalogo_delito
        EXCEPT
        SELECT id_delito, id_bien_juridico, clave2, delito, activo
        FROM dbo.federal_catalogo_delito
        WHERE id_delito <= 49
    )
    OR EXISTS
    (
        SELECT id_delito, id_bien_juridico, clave2, delito, activo
        FROM dbo.federal_catalogo_delito
        WHERE id_delito <= 49
        EXCEPT
        SELECT id_delito, id_bien_juridico, clave2, delito, activo
        FROM dbo.catalogo_delito
    )
        THROW 51121, 'Los 49 delitos comunes no coinciden con el catálogo Mensual.', 1;

    IF EXISTS
    (
        SELECT id_subtipo_delito, id_delito, clave3, subtipo_delito, activo
        FROM dbo.catalogo_subtipo_delito
        EXCEPT
        SELECT id_subtipo_delito, id_delito, clave3, subtipo_delito, activo
        FROM dbo.federal_catalogo_subtipo_delito
        WHERE id_subtipo_delito <= 79
    )
    OR EXISTS
    (
        SELECT id_subtipo_delito, id_delito, clave3, subtipo_delito, activo
        FROM dbo.federal_catalogo_subtipo_delito
        WHERE id_subtipo_delito <= 79
        EXCEPT
        SELECT id_subtipo_delito, id_delito, clave3, subtipo_delito, activo
        FROM dbo.catalogo_subtipo_delito
    )
        THROW 51122, 'Los 79 subtipos comunes no coinciden con el catálogo Mensual.', 1;

    IF EXISTS
    (
        SELECT id_modalidad_delito, id_subtipo_delito, clave4, modalidad_delito, id_admite_tentativa, activo
        FROM dbo.catalogo_modalidad_delito
        EXCEPT
        SELECT id_modalidad_delito, id_subtipo_delito, clave4, modalidad_delito, id_admite_tentativa, activo
        FROM dbo.federal_catalogo_modalidad_delito
        WHERE es_fuero_federal = 0
    )
    OR EXISTS
    (
        SELECT id_modalidad_delito, id_subtipo_delito, clave4, modalidad_delito, id_admite_tentativa, activo
        FROM dbo.federal_catalogo_modalidad_delito
        WHERE es_fuero_federal = 0
        EXCEPT
        SELECT id_modalidad_delito, id_subtipo_delito, clave4, modalidad_delito, id_admite_tentativa, activo
        FROM dbo.catalogo_modalidad_delito
    )
        THROW 51123, 'Las 83 modalidades comunes no coinciden con el catálogo Mensual.', 1;

    IF EXISTS
    (
        SELECT
            id_modalidad_delito,
            id_grado_consumacion,
            id_instrumento_comision,
            id_forma_accion,
            delito_sabana,
            subtipo_delito_sabana,
            modalidad_delito_sabana,
            clave2_sabana,
            clave3_sabana,
            activo
        FROM dbo.catalogo_delito_sabana
        EXCEPT
        SELECT
            id_modalidad_delito,
            id_grado_consumacion,
            id_instrumento_comision,
            id_forma_accion,
            delito_sabana,
            subtipo_delito_sabana,
            modalidad_delito_sabana,
            clave2_sabana,
            clave3_sabana,
            activo
        FROM dbo.federal_catalogo_delito_sabana
        WHERE es_fuero_federal = 0
    )
    OR EXISTS
    (
        SELECT
            id_modalidad_delito,
            id_grado_consumacion,
            id_instrumento_comision,
            id_forma_accion,
            delito_sabana,
            subtipo_delito_sabana,
            modalidad_delito_sabana,
            clave2_sabana,
            clave3_sabana,
            activo
        FROM dbo.federal_catalogo_delito_sabana
        WHERE es_fuero_federal = 0
        EXCEPT
        SELECT
            id_modalidad_delito,
            id_grado_consumacion,
            id_instrumento_comision,
            id_forma_accion,
            delito_sabana,
            subtipo_delito_sabana,
            modalidad_delito_sabana,
            clave2_sabana,
            clave3_sabana,
            activo
        FROM dbo.catalogo_delito_sabana
    )
        THROW 51124, 'Las 5,976 combinaciones comunes no coinciden con la sábana Mensual.', 1;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

SELECT N'federal_catalogo_bien_juridico' AS catalogo, COUNT(*) AS registros, SUM(CASE WHEN activo = 1 THEN 1 ELSE 0 END) AS activos
FROM dbo.federal_catalogo_bien_juridico
UNION ALL
SELECT N'federal_catalogo_delito', COUNT(*), SUM(CASE WHEN activo = 1 THEN 1 ELSE 0 END)
FROM dbo.federal_catalogo_delito
UNION ALL
SELECT N'federal_catalogo_subtipo_delito', COUNT(*), SUM(CASE WHEN activo = 1 THEN 1 ELSE 0 END)
FROM dbo.federal_catalogo_subtipo_delito
UNION ALL
SELECT N'federal_catalogo_modalidad_delito', COUNT(*), SUM(CASE WHEN activo = 1 THEN 1 ELSE 0 END)
FROM dbo.federal_catalogo_modalidad_delito
UNION ALL
SELECT N'federal_catalogo_delito_sabana', COUNT(*), SUM(CASE WHEN activo = 1 THEN 1 ELSE 0 END)
FROM dbo.federal_catalogo_delito_sabana;

SELECT
    es_fuero_federal,
    COUNT(*) AS modalidades
FROM dbo.federal_catalogo_modalidad_delito
GROUP BY es_fuero_federal
ORDER BY es_fuero_federal;

SELECT
    es_fuero_federal,
    COUNT(*) AS combinaciones_sabana
FROM dbo.federal_catalogo_delito_sabana
GROUP BY es_fuero_federal
ORDER BY es_fuero_federal;

SELECT id_modulo, clave, nombre, activo
FROM dbo.catalogo_modulo
WHERE clave = N'FEDERAL';
GO
